sys_script.script:
(function executeRule(current, previous) {

    if (current.customer_type + '' !== 'Trade') return;

    try {

        var resolver = new CLMUserResolver();
        var router   = new CLMApprovalRouter();

        // Step 1: Get target role
        var result = router.getApprover(
            current.segment,
            current.customer_type,
            current.net_exposure,
            current.nod_days,
            current.is_deviation,
            current.implied_multiplier,
            current.customer_vintage_days,
            current.system_multiplier
        );

        var targetRole = result.role;

        // Step 2: Get hierarchy
        var key = current.segment + '_Trade';

        if (!CLM_ROLE_HIERARCHIES[key]) {
            gs.error('No hierarchy found for ' + key);
            return;
        }

        var hierarchy = CLM_ROLE_HIERARCHIES[key];

        // Step 3: Build sequence
        var sequence = buildApproverSequence(
            hierarchy,
            targetRole,
            resolver,
            current.region,
            current.zone,
            current.segment,
            current.depot
        );

        // Step 4: Store JSON
        current.u_approver_sequence = JSON.stringify(sequence);
        current.u_current_approver_order = 1;

        gs.info('Sequence created: ' + current.u_approver_sequence);

    } catch (e) {
        gs.error('SEQ ERROR: ' + e.message);
    }

})(current, previous);
